+        RuleViolationFileNameStrategy strategy = strategyFor(properties);
+        boolean useRandomNames = !strategyFromConstructor && FILE_NAMES_RANDOM.equals(
+                properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM));
