+    private RuleViolationFileNameStrategy strategyFor(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (strategyFromConstructor) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+        if (configured == null || FILE_NAMES_RANDOM.equals(configured)) {
+            return constructorStrategy;
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::createDescriptionBasedFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new IllegalArgumentException("not a RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate RuleViolationFileNameStrategy configured by %s=%s; it must be a class with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), ignored ->
+                    new FileSyncedProperties(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void checkStoreFolder(File configuredFolder, Path folderPath) {
+        try {
+            if (Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS) && !Files.isDirectory(folderPath)) {
+                throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", configuredFolder));
+            }
+        } catch (SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void ensureFolderExists(File configuredFolder, Path folderPath) {
+        try {
+            Files.createDirectories(folderPath);
+            if (!Files.isDirectory(folderPath)) {
+                throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", configuredFolder));
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void createIndex(Path indexPath) {
+        try {
+            if (!Files.exists(indexPath, LinkOption.NOFOLLOW_LINKS)) {
+                Files.createFile(indexPath);
+            }
+            if (!Files.isRegularFile(indexPath, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "The stored rules index must be a regular file directly in the store folder: %s", indexPath));
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadRulesFrom(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = rule.getDescription();
+            String existingName = storedRules.getProperty(description);
+            if (violations.isEmpty() && integrityModeForSaveIsRepair()) {
+                forgetRuleOnRepair(description, existingName);
+                return;
+            }
+
+            String ruleFileName = existingName != null ? existingName : createRuleFileName(description);
+            Path writePath = validateWritePath(ruleFileName, description);
+            write(violations, writePath);
+            if (existingName == null) {
+                Properties properties = storedRules.loadedProperties();
+                properties.setProperty(description, ruleFileName);
+                try {
+                    syncFileSystem(storedRules.propertiesFile, properties);
+                } catch (RuntimeException e) {
+                    properties.remove(description);
+                    throw e;
+                }
+            }
+        }
+    }
+
+    private boolean integrityModeForSaveIsRepair() {
+        // The mode is fixed for an initialized instance. It is represented by the same field as the strategy state
+        // to keep the public object small; save-time cleanup is only enabled when repair was selected.
+        return integrityMode == IntegrityMode.REPAIR;
+    }
+
+    private IntegrityMode integrityMode = IntegrityMode.IGNORE;
+
+    private void forgetRuleOnRepair(String description, String existingName) {
+        if (existingName == null) {
+            return;
+        }
+        Properties properties = storedRules.loadedProperties();
+        boolean shared = isShared(description, existingName, properties, storeFolder.toPath().toAbsolutePath().normalize());
+        PathResolution resolution = resolve(existingName, storeFolder.toPath().toAbsolutePath().normalize());
+        if (!shared && resolution.isSafeStoreFile()) {
+            if (isIndexFile(resolution.target, storedRules.propertiesFile.toPath())) {
+                throw new StoreUpdateFailedException("A rule violation file must not be the stored.rules index");
+            }
+            try {
+                deleteNamedFile(resolution);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        properties.remove(description);
+        try {
+            syncFileSystem(storedRules.propertiesFile, properties);
+        } catch (RuntimeException e) {
+            properties.setProperty(description, existingName);
+            throw e;
+        }
+    }
+
+    private String createRuleFileName(String description) {
+        String result = constructorStrategy.createRuleFileName(description);
+        if (result == null || result.isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
+        }
+        return result;
+    }
+
+    private Path validateWritePath(String fileName, String description) {
+        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        Path path = pathFromName(fileName, folderPath);
+        if (path == null) {
+            throw new StoreUpdateFailedException(String.format("Invalid rule violation file name for '%s': %s", description, fileName));
+        }
+        try {
+            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                if (!Files.isRegularFile(path)) {
+                    throw new StoreUpdateFailedException(String.format("Rule violation file is not a regular file: %s", fileName));
+                }
+                Path target = path.toRealPath();
+                if (!isDirectChild(target, folderRealPath(folderPath)) || isIndexFile(target, storedRules.propertiesFile.toPath())) {
+                    throw unsafeWrite(fileName);
+                }
+            } else {
+                if (!isDirectChild(path, folderPath) || isSameNormalizedPath(path, storedRules.propertiesFile.toPath())) {
+                    throw unsafeWrite(fileName);
+                }
+            }
+            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS) && isIndexFile(path, storedRules.propertiesFile.toPath())) {
+                throw unsafeWrite(fileName);
+            }
+            return path;
+        } catch (IOException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private StoreUpdateFailedException unsafeWrite(String fileName) {
+        return new StoreUpdateFailedException(String.format(
+                "Refusing to write rule violations to '%s': the name must resolve to a file directly in the store folder and must not be the stored.rules index",
+                fileName));
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8),
+                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            if (ruleDetailsFileName == null) {
+                throw new IllegalArgumentException(String.format("No rule stored with description '%s'", rule.getDescription()));
+            }
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (containsOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            String result = new String(toByteArray(new File(storeFolder, fileName)), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException | SecurityException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private IntegrityAnalysis inspect(Properties properties, Path folderPath, Path indexPath,
+                                     RuleViolationFileNameStrategy strategy, boolean useRandomNames) {
+        Path realFolder = folderRealPath(folderPath);
+        List<EntryInfo> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String name = properties.getProperty(description);
+            String derived = useRandomNames ? null : derivedName(strategy, description);
+            EntryInfo entry = new EntryInfo(description, name, derived, resolve(name, folderPath));
+            if (!entry.resolution.broken && isEmptyViolationFile(entry.resolution.path)) {
+                entry.resolved = true;
+            }
+            entries.add(entry);
+        }
+
+        markShared(entries);
+        markColliding(entries);
+        markMisplacedAndOccupied(entries, properties, folderPath, realFolder);
+        List<String> unownedFiles = findUnownedFiles(entries, folderPath, indexPath);
+        return new IntegrityAnalysis(entries, unownedFiles);
+    }
+
+    private String derivedName(RuleViolationFileNameStrategy strategy, String description) {
+        String result;
+        try {
+            result = strategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not derive a rule violation file name for rule '%s'", description), e);
+        }
+        if (result == null || result.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private void markShared(List<EntryInfo> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                EntryInfo left = entries.get(i);
+                EntryInfo right = entries.get(j);
+                if (left.name.equals(right.name) || sameFile(left.resolution, right.resolution)) {
+                    left.shared = true;
+                    right.shared = true;
+                }
+            }
+        }
+    }
+
+    private boolean sameFile(PathResolution left, PathResolution right) {
+        if (left.target == null || right.target == null) {
+            return false;
+        }
+        try {
+            return Files.isSameFile(left.target, right.target);
+        } catch (IOException | SecurityException e) {
+            return left.target.equals(right.target);
+        }
+    }
+
+    private void markColliding(List<EntryInfo> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                EntryInfo left = entries.get(i);
+                EntryInfo right = entries.get(j);
+                if (left.derived != null && left.derived.equals(right.derived)) {
+                    left.colliding = true;
+                    right.colliding = true;
+                }
+            }
+        }
