        Properties properties = storedRules.loadedProperties();
        boolean shared = isShared(description, existingName, properties, storeFolder.toPath().toAbsolutePath().normalize());
        PathResolution resolution = resolve(existingName, storeFolder.toPath().toAbsolutePath().normalize());
        if (!shared && resolution.isSafeStoreFile()) {
            if (isIndexFile(resolution.target, storedRules.propertiesFile.toPath())) {
                throw new StoreUpdateFailedException("A rule violation file must not be the stored.rules index");
            }
            try {
                deleteNamedFile(resolution);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
