    private Path validateWritePath(String fileName, String description) {
        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
        Path path = pathFromName(fileName, folderPath);
        if (path == null) {
            throw new StoreUpdateFailedException(String.format("Invalid rule violation file name for '%s': %s", description, fileName));
        }
        try {
            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                if (!Files.isRegularFile(path)) {
                    throw new StoreUpdateFailedException(String.format("Rule violation file is not a regular file: %s", fileName));
                }
                Path target = path.toRealPath();
                if (!isDirectChild(target, folderRealPath(folderPath)) || isIndexFile(target, storedRules.propertiesFile.toPath())) {
