            } else {
                if (!isDirectChild(path, folderPath) || isSameNormalizedPath(path, storedRules.propertiesFile.toPath())) {
                    throw unsafeWrite(fileName);
                }
            }
            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS) && isIndexFile(path, storedRules.propertiesFile.toPath())) {
                throw unsafeWrite(fileName);
