    private static class ViolationStoreLineBreakAdapter {
        private final ViolationStore store;

        ViolationStoreLineBreakAdapter(ViolationStore store) {
            this.store = checkNotNull(store);
        }

        void initialize(Properties properties) {
            store.initialize(properties);
        }

        boolean contains(ArchRule rule) {
            ArchRule matchingRule = findMatchingStoredRule(rule);
            return store.contains(matchingRule);
        }

        List<String> getViolations(ArchRule rule) {
            return ensureUnixLineBreaks(store.getViolations(findMatchingStoredRule(rule)));
        }

        void save(ArchRule rule, List<String> violations) {
            store.save(findMatchingStoredRule(rule), ensureUnixLineBreaks(violations));
        }

        private ArchRule findMatchingStoredRule(ArchRule rule) {
            if (store.contains(rule)) {
                return rule;
            }
            if (store instanceof TextFileBasedViolationStore) {
                String matchingDescription = ((TextFileBasedViolationStore) store)
                        .findDescriptionIgnoringLineBreaks(rule.getDescription());
                if (matchingDescription != null) {
                    return rule.as(matchingDescription);
                }
            }
            return rule;
        }
    }

    private static class EvaluationResultLineBreakAdapter {
        private final EvaluationResult result;

        private EvaluationResultLineBreakAdapter(EvaluationResult result) {
            this.result = checkNotNull(result);
        }

        List<String> getViolations() {
            return ensureUnixLineBreaks(result.getFailureReport().getDetails());
        }

        Priority getPriority() {
            return result.getPriority();
        }

        EvaluationResult filterDescriptionsMatching(Predicate<String> predicate) {
            return result.filterDescriptionsMatching(input -> predicate.test(ensureUnixLineBreaks(input)));
        }
